let recoverySequence=0;
function recoveryEntries(){return [...$('disk-recovery-entries').children].map(row=>({type:row.querySelector('.recovery-type').value,label:row.querySelector('.recovery-label').value,identifier:row.querySelector('.recovery-identifier').value,key:row.querySelector('.recovery-key').value})).filter(k=>k.label||k.identifier||k.key);}
function addRecovery(entry={}){if($('disk-recovery-entries').children.length>=16){notice(t('Añade como máximo 16 claves de recuperación.'));return;}const id='manual-recovery-'+(++recoverySequence),row=document.createElement('div');row.className='recovery-entry';row.innerHTML=`<div class="split fields"><div><label for="${id}-type">Tipo de cifrado</label><select id="${id}-type" class="recovery-type"><option value="bitlocker">BitLocker (48 dígitos)</option><option value="luks">LUKS1 / LUKS2 (Linux)</option></select></div><div><label for="${id}-label">Equipo o disco</label><input id="${id}-label" class="recovery-label" maxlength="128" placeholder="Ejemplo: portátil de rescate"></div></div><label for="${id}-identifier">UUID o ID de recuperación · opcional</label><input id="${id}-identifier" class="recovery-identifier" maxlength="128" placeholder="Identificador del disco o de la clave"><label for="${id}-key">Contraseña o clave de recuperación</label><div class="secret"><input id="${id}-key" class="recovery-key" type="password" autocomplete="new-password" maxlength="4096" spellcheck="false"><button type="button" class="reveal" data-for="${id}-key" aria-label="Mostrar clave de recuperación">◉</button></div><button type="button" class="quiet recovery-remove">Quitar esta clave</button>`;$('disk-recovery-entries').append(row);I18n.translateTree(row);row.querySelector('.recovery-type').value=entry.type||'bitlocker';for(const name of ['label','identifier','key'])row.querySelector('.recovery-'+name).value=entry[name]||'';row.querySelector('.recovery-remove').addEventListener('click',()=>{row.remove();invalidatePrepared();updateSummary();});}
function fillRecovery(entries){$('disk-recovery-entries').replaceChildren();for(const entry of entries)addRecovery(entry);if(!entries.length)addRecovery();updateSummary();}
$('disk-recovery-add').addEventListener('click',()=>{addRecovery();updateSummary();});
addRecovery();
function preparationInput(){const mode=document.querySelector('input[name=protection]:checked').value;const result={capsule:capsule(),diskRecovery:recoveryEntries(),protection:{mode,passphrase:mode==='encrypted'?($('password-unified').checked?$('ssh-password').value:$('unlock-password').value):''}};if(bitlockerState.available&&$('bitlocker-inject')?.checked&&bitlockerState.cachedKey){result.bitlocker=[bitlockerState.cachedKey];}return result;}
function setPrepared(value){prepared=value;$('prepared-status').hidden=false;$('prepared-status').textContent='✓ '+prepared.name+' · '+fmt(prepared.bytes)+t(' · Lectura SHA-256 verificada. Imagen privada lista.');updateFlashState();}
