function updateFlashState(){
 const disk=$('usb-disks').value===''?null:disks[Number($('usb-disks').value)];
 $('flash').disabled=busy||!image||!disk;
 $('flash').textContent=prepared?t('Grabar USB'):t('Preparar y grabar USB');
 $('flash-status').textContent=busy?t('Espera a que termine la operación actual.'):!image?t('Selecciona una imagen en el primer paso.'):!disk?t('Busca y selecciona un USB desmontado.'):image.bytes>disk.size?t('La imagen no cabe en este USB. Elige uno con más capacidad.'):prepared?t('Todo listo. Confirma el USB en la siguiente ventana.'):t('Todo listo: prepararemos tu imagen y grabaremos el USB. ')+($('usb-backup').checked?t('Con respaldo previo.'):t('Se borrará el contenido anterior, sin respaldo.'));
 if(disk&&image?.bytes>disk.size)$('flash').disabled=true;
}
$('disks-refresh').addEventListener('click',async()=>{const r=await call('disks');if(!r)return;disks=r.disks;$('usb-disks').replaceChildren();const blank=document.createElement('option');blank.value='';blank.textContent=disks.length?t('Elige un USB desmontado'):t('No hay USB desmontados disponibles');$('usb-disks').append(blank);for(const [i,d]of disks.entries()){const opt=document.createElement('option');opt.value=i;opt.textContent=d.model+' · '+fmt(d.size)+' · '+d.serial;$('usb-disks').append(opt);}updateFlashState();});
$('usb-disks').addEventListener('change',updateFlashState);
$('usb-backup').addEventListener('change',updateFlashState);
