$('cancel-download').addEventListener('click',()=>window.aguja.cancelDownload());
let transfer={phase:'',time:0,done:0};
window.aguja.onProgress(p=>{$('cancel-download').hidden=!p.cancellable;$('cancel-download').disabled=false;$('progress').hidden=false;const captions={download:t('Descargando la imagen oficial…'),verify:t('Comprobando SHA-256…'),prepare:(p.message?t(p.message):null)||t('Preparando tu imagen privada…'),flash:(p.message?t(p.message):null)||t('Respaldando y grabando…')};$('progress-message').textContent=captions[p.phase]||t('Trabajando…');if(p.total){$('progress-bar').max=p.total;$('progress-bar').value=p.done||0;const now=Date.now();if(transfer.phase!==p.phase||p.done<transfer.done)transfer={phase:p.phase,time:now,done:p.done||0};const seconds=(now-transfer.time)/1000,rate=seconds>1?((p.done||0)-transfer.done)/seconds:0,eta=rate>0?Math.ceil((p.total-(p.done||0))/rate):0;$('progress-count').textContent=Math.floor(100*(p.done||0)/p.total)+'% · '+fmt(p.done||0)+' / '+fmt(p.total)+(rate>0?' · '+(rate/1048576).toFixed(1)+' MiB/s · ~'+Math.ceil(eta/60)+' min':'');}else{$('progress-bar').removeAttribute('value');$('progress-count').textContent='';}});
async function readBitLockerKey(){const vol=bitlockerState.activeVolume;if(!vol||!vol.hasRecoveryPassword)return null;const key=await call('bitlockerKey',[vol.mountPoint]);if(!key||!/^(?:\d{6}-){7}\d{6}$/.test(key.recoveryPassword||''))return null;bitlockerState.cachedKey=key;return key;}
function updateBitLockerUI(){
 if(!bitlockerState.available)return;
 $('bitlocker-check-btn').disabled=busy;
 const vol=bitlockerState.activeVolume;
 if(!vol){
  $('bitlocker-badge').textContent=t(bitlockerState.requiresElevation?'Pendiente de autorización':bitlockerState.error?'No se pudo comprobar BitLocker. Vuelve a intentarlo.':'Sin unidades');
  $('bitlocker-badge').className='badge missing';
  $('bitlocker-vol-status').textContent=t(bitlockerState.error|| (bitlockerState.requiresElevation?'Se necesitan permisos de Windows para consultar BitLocker. Pulsa Comprobar BitLocker y acepta UAC.':'No se detectaron unidades protegidas.'));
  $('bitlocker-suspend-btn').hidden=true;$('bitlocker-resume-btn').hidden=true;$('bitlocker-view-key-btn').disabled=true;$('bitlocker-export-key-btn').disabled=true;$('bitlocker-inject').disabled=true;return;
 }
 const isProtected=vol.protectionStatus==='On';
 $('bitlocker-badge').textContent=isProtected?t('Protegido'):t('Suspendido');$('bitlocker-badge').className=isProtected?'badge':'badge missing';
 const desc=[vol.mountPoint,vol.capacityGB?vol.capacityGB+' GB':'',vol.encryptionMethod,vol.encryptionPercentage+' %',isProtected?t('Protección activada'):t('Protección suspendida')].filter(Boolean).join(' · ');$('bitlocker-vol-status').textContent=desc;
 $('bitlocker-suspend-btn').hidden=!isProtected;$('bitlocker-suspend-btn').disabled=busy;$('bitlocker-resume-btn').hidden=isProtected;$('bitlocker-resume-btn').disabled=busy;
 $('bitlocker-view-key-btn').disabled=busy||!vol.hasRecoveryPassword;$('bitlocker-export-key-btn').disabled=busy||!vol.hasRecoveryPassword;$('bitlocker-inject').disabled=busy||!vol.hasRecoveryPassword;
 if(!vol.hasRecoveryPassword)$('bitlocker-inject').checked=false;
}
async function refreshBitLocker(keepSelected=true,authorize=false){
 if(!bitlockerState.available)return;
 const res=await call('bitlockerStatus',[authorize]);
 $('bitlocker-card').hidden=false;
 bitlockerState.requiresElevation=Boolean(res?.requiresElevation);bitlockerState.error=res?.error||(!res?'No se pudo comprobar BitLocker. Vuelve a intentarlo.':null);
 bitlockerState.volumes=res?.volumes||[];const prevMount=keepSelected?bitlockerState.activeVolume?.mountPoint:null;
 $('bitlocker-volume').replaceChildren();
 if(!bitlockerState.volumes.length){const opt=document.createElement('option');opt.value='';opt.textContent=t(bitlockerState.requiresElevation?'Pendiente de autorización':bitlockerState.error?'No se pudo comprobar BitLocker. Vuelve a intentarlo.':'No se detectaron unidades BitLocker');$('bitlocker-volume').append(opt);bitlockerState.activeVolume=null;bitlockerState.cachedKey=null;updateBitLockerUI();return;}
 for(const v of bitlockerState.volumes){const opt=document.createElement('option');opt.value=v.mountPoint;const prot=v.protectionStatus==='On'?t('Protegido'):t('Suspendido');opt.textContent=`${v.mountPoint} (${v.volumeType==='OperatingSystem'?t('Sistema'):t('Datos')}, ${v.capacityGB} GB · ${prot})`;$('bitlocker-volume').append(opt);}
 $('bitlocker-volume').value=bitlockerState.volumes.some(v=>v.mountPoint===prevMount)?prevMount:bitlockerState.volumes[0].mountPoint;
 bitlockerState.activeVolume=bitlockerState.volumes.find(v=>v.mountPoint===$('bitlocker-volume').value);bitlockerState.cachedKey=null;updateBitLockerUI();updateSummary();
}
