$('bitlocker-volume').addEventListener('change',()=>{bitlockerState.activeVolume=bitlockerState.volumes.find(v=>v.mountPoint===$('bitlocker-volume').value)||null;bitlockerState.cachedKey=null;updateBitLockerUI();invalidatePrepared();updateSummary();});
