$('bitlocker-suspend-btn').addEventListener('click',async()=>{const vol=bitlockerState.activeVolume;if(!vol)return;const r=await call('bitlockerSuspend',[vol.mountPoint,1],t('BitLocker suspendido en ')+vol.mountPoint+t(' para 1 reinicio.'));if(r){vol.protectionStatus=r.protectionStatus;updateBitLockerUI();}});
